export const FIELD_TEST_NOTE='Field test — November 19, 2026. Run data is not accurate; do not use this shift to assess delivery travel performance.';
export const activeRunForShift=(state,shiftId)=>state.runs.find(r=>r.status==='active'&&r.shiftId===shiftId);
export function annotateFieldTest(state,shiftIds=[]){const selected=new Set(shiftIds);let changed=false;for(const s of state.shifts){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(s.startedAt));if(selected.has(s.id)&&day==='2026-11-19'&&!s.runDataQuality){s.runDataQuality='field-test-inaccurate';s.fieldTestNote=FIELD_TEST_NOTE;changed=true;}}return changed;}
export function runKind(state,run){const ds=state.deliveries.filter(d=>run.deliveryIds.includes(d.id)&&d.status!=='canceled'),completed=Array.isArray(run.completedDeliveryIds)?run.completedDeliveryIds:ds.filter(d=>d.status==='delivered'&&!run.unfinishedDeliveryIds?.includes(d.id)&&(!run.returnedAt||!d.completedAt||Date.parse(d.completedAt)<=Date.parse(run.returnedAt))).map(d=>d.id);return ((run.status==='returned'||run.completedAt)?completed:ds).length>1?'batch':'single';}
export function normalizeRunKinds(state){for(const r of state.runs){r.kind=runKind(state,r);if(r.status==='returned'||r.completedAt)for(const d of state.deliveries.filter(d=>(r.completedDeliveryIds||r.deliveryIds).includes(d.id)&&d.status==='delivered'))d.deliveryMode=r.kind;}}

export function detachBatchOrder(state,deliveryId){const d=state.deliveries.find(d=>d.id===deliveryId);if(!d?.batchId||!['pending','ready','active'].includes(d.status))throw Error('Only an unfinished order can leave its batch.');const previous=d.batchId;d.batchId=null;d.deliveryMode='single';delete d.scheduledPriority;delete d.scheduledPriorityDecided;delete d.batchPosition;if(!state.deliveries.some(x=>x.batchId===previous&&x.status!=='canceled'))for(const r of state.runs.filter(r=>r.batchId===previous))r.batchId=null;normalizeRunKinds(state);return previous;}
export function assignOrders(state,shiftId,ids,batchId){const unique=[...new Set(ids)];if(!unique.length)throw Error('Select at least one order.');const ds=unique.map(id=>state.deliveries.find(d=>d.id===id));if(ds.some(d=>!d||d.shiftId!==shiftId||d.batchId||!['pending','ready'].includes(d.status)||state.runs.some(r=>r.status==='active'&&r.deliveryIds.includes(d.id))))throw Error('Choose pending or ready single orders from this shift.');const members=state.deliveries.filter(d=>d.shiftId===shiftId&&d.batchId===batchId&&d.status!=='canceled');if(members.length&&members.every(d=>d.status==='delivered'))throw Error('This batch is already complete. Choose a new batch.');let position=Math.max(-1,...members.map(d=>d.batchPosition??0))+1;const run=state.runs.find(r=>r.shiftId===shiftId&&r.batchId===batchId&&r.status==='active');for(const d of ds){d.batchId=batchId;d.deliveryMode='batch';d.batchPosition=position++;if(run&&d.status==='ready'){d.status='active';d.departedAt=new Date().toISOString();run.deliveryIds.push(d.id);delete run.completedAt;delete run.completionKind;}}normalizeRunKinds(state);}
export function finishRunEarly(state,runId,at){const run=state.runs.find(r=>r.id===runId&&r.status==='active');if(!run)throw Error('No active run was found.');if(!Number.isFinite(Date.parse(at))||Date.parse(at)<Date.parse(run.startedAt))throw Error('Return time cannot precede departure.');run.completedDeliveryIds=state.deliveries.filter(d=>run.deliveryIds.includes(d.id)&&d.status==='delivered').map(d=>d.id);const unfinished=state.deliveries.filter(d=>run.deliveryIds.includes(d.id)&&d.status==='active');for(const d of unfinished){d.status='ready';delete d.departedAt;}run.returnedAt=at;run.status='returned';run.completionKind=unfinished.length?'ended-with-unfinished':'restaurant-return';if(unfinished.length)run.unfinishedDeliveryIds=unfinished.map(d=>d.id);normalizeRunKinds(state);return run;}
export function confirmPhotoException(delivery,at){if(!delivery?.isCatering)throw Error('This is not a catering order.');delivery.cateringPhotoException={confirmedAt:at,reason:'Driver explicitly confirmed completion without both required photos.'};}
export function deliveryNotes(delivery,value){const notes=String(value??'').trim();if(notes.length>4000)throw Error('Keep delivery notes under 4,000 characters.');delivery.notes=notes;}
export function mapProvider(settings){return settings?.mapsProvider==='google'?'google':'apple';}
export function providerName(settings){return mapProvider(settings)==='google'?'Google Maps':'Apple Maps';}
export function directionsURL(addresses,settings={},normalize=a=>a){if(!addresses.length)throw Error('No stops to navigate.');const stops=addresses.map(normalize);if(mapProvider(settings)==='google'){if(stops.length>4)throw Error('Open this Google Maps route in groups of up to four stops.');const u=new URL('https://www.google.com/maps/dir/');u.searchParams.set('api','1');u.searchParams.set('travelmode','driving');u.searchParams.set('dir_action','navigate');u.searchParams.set('destination',stops.at(-1));if(stops.length>1)u.searchParams.set('waypoints',stops.slice(0,-1).join('|'));return u.href;}const u=new URL('https://maps.apple.com/directions');u.searchParams.set('mode','driving');u.searchParams.set('destination',stops.at(-1));for(const a of stops.slice(0,-1))u.searchParams.append('waypoint',a);return u.href.replaceAll('+','%20');}

export function canUndoRunStart(state,runId){
 const run=state.runs.find(r=>r.id===runId);
 if(!run||run.status!=='active'||run.returnedAt||run.completedAt)return false;
 const orders=run.deliveryIds.map(id=>state.deliveries.find(d=>d.id===id));
 return orders.length>0&&orders.every(d=>d&&['active','canceled'].includes(d.status)&&!d.completedAt)&&orders.some(d=>d.status==='active');
}
export function undoRunStart(state,runId){
 if(!canUndoRunStart(state,runId))throw Error('This start can no longer be undone. A delivery has been completed or the run has ended.');
 const run=state.runs.find(r=>r.id===runId);
 if(!state.shifts.some(s=>s.id===run.shiftId&&s.status==='active'))throw Error('Only the current shift’s start can be undone.');
 for(const d of state.deliveries.filter(d=>run.deliveryIds.includes(d.id)&&d.status==='active')){d.status='ready';delete d.departedAt;}
 state.runs=state.runs.filter(r=>r.id!==runId);
 return run;
}
